(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const wx = w1x + Math.sin(w1y*0.05+t*0.4)*6 + Math.cos(w1x*0.04-t*0.3)*5;
  const wy = w1y + Math.cos(w1x*0.05-t*0.35)*6 + Math.sin(w1y*0.04+t*0.25)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*55, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*85, 200+Math.sin(t*0.75+1)*65, 0.075, 2.4, 1.05],
    [200+Math.sin(t*0.38+6)*110, 220+Math.cos(t*0.48+3)*75, 0.095, 1.8, 0.95]
  ];
  let aS=0, iS=0, cS=0, harm=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1 = Math.sin(d*f-t*sp);
    const w2 = Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS += w1*w;
    iS += w2*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+2.0)*w*0.6;
    harm += Math.cos(d*f*0.5+t*sp*0.3)*w;
  }
  const n=9;
  const act=aS/n, inh=iS/n, cross=cS/n, harmonic=harm/n;
  let fbm = 0, amp = 1, freq = 0.04;
  for (let i=0; i<5; i++) {
    fbm += Math.sin(sx*freq+sy*freq*0.8+t*(0.8+i*0.3)+i*1.7)*amp;
    fbm += Math.sin(sx*freq*0.7-sy*freq*1.1+t*(1.1+i*0.2)+i*2.3)*amp*0.7;
    amp *= 0.5; freq *= 2.1;
  }
  fbm /= 2.5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5), sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const spiral = (sp1+sp2)*0.4;
  const sp3 = Math.sin(dist*0.08-ang*2-t*2.1)*0.25, sp4 = Math.sin(dist*0.03+ang*6+t*0.9)*0.2;
  const spiral2 = sp3+sp4;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.sin(sx*0.08+1)*Math.cos(sy*0.12-0.5)+Math.sin((sx-sy)*0.07+t*0.7)*0.4)*1.2)*0.25;
  const rd1 = act - inh*0.7;
  const rd2 = cross - harmonic*0.5;
  const rd = rd1*0.6 + rd2*0.4;
  const texture = fbm*0.3 + spiral*0.25 + spiral2*0.15 + cell*0.15 + cell2*0.15;
  const reaction = Math.tanh((rd + texture)*2.0);
  const contour = 1.0 - Math.pow(Math.abs(Math.sin(reaction*Math.PI*3)), 8)*0.15;
  const glow = Math.exp(-Math.abs(reaction)*3)*0.3*(0.7+Math.sin(t*0.8)*0.3);
  const v = (reaction*0.65 + glow)*0.5 + 0.5;
  const pal = [
    [5,10,45],[10,35,80],[12,65,105],[18,110,130],
    [45,160,140],[130,190,100],[200,200,70],
    [220,160,60],[210,110,55],[180,65,60],
    [130,35,65],[70,20,60],[30,12,50],[5,10,45]
  ];
  const idx = Math.max(0, Math.min(v*(pal.length-1), pal.length-1.001));
  const i = idx|0, f = idx-i;
  const r = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = (0.85+Math.sin(reaction*Math.PI)*0.15)*contour;
  const edge = Math.abs(reaction)>0.75 ? 1.12 : 1.0;
  const highlight = reaction>0.6 ? (reaction-0.6)*0.5 : 0;
  return [
    Math.min(255, ((r+highlight*60)*lum*edge)|0),
    Math.min(255, ((g+highlight*40)*lum*edge)|0),
    Math.min(255, ((b+highlight*20)*lum*edge)|0)
  ];
}
